def should_replace_metric_family(
    is_full_run: bool,
    family: str,
    metrics: list[dict],
) -> bool:
    """å®Œæ•´è¿è¡Œå¯ç¡®è®¤ç©ºç»“æžœï¼›é€‰æ‹©æ€§çŸ­æ‰¹æ¬¡ç©ºç»“æžœé»˜è®¤ä¿ç•™æ—§äº‹å®žã€‚"""
    if is_full_run:
        return True
    allowed = set(pp.METRIC_FAMILIES[family])
    return any(item.get("metric_type") in allowed for item in metrics)


